/**
 * Responsive image sets generated by scripts/prepare-assets.py.
 * Files are named `<name>-<width>.webp`; Vite fingerprints them for long-term caching.
 */
const files = import.meta.glob('./assets/img/*.webp', { eager: true, query: '?url', import: 'default' }) as Record<
	string,
	string
>;

export type ImageSet = { src: string; srcset: string; width: number; height: number };

const RATIOS: Record<string, number> = { cover: 4 / 3, wide: 9 / 16, 'brand-banner': 765 / 2056, logo: 1 };

export function imageSet(name: string): ImageSet {
	const variants = Object.entries(files)
		.map(([path, url]) => {
			const match = path.match(/\/([^/]+)-(\d+)\.webp$/);
			return match && match[1] === name ? { url, width: Number(match[2]) } : null;
		})
		.filter((v): v is { url: string; width: number } => v !== null)
		.sort((a, b) => a.width - b.width);
	if (!variants.length) throw new Error(`Missing image set: ${name}`);

	const largest = variants[variants.length - 1];
	const kind = Object.keys(RATIOS).find((k) => name === k || name.endsWith(`-${k}`)) ?? 'wide';
	return {
		src: variants[0].url,
		srcset: variants.map((v) => `${v.url} ${v.width}w`).join(', '),
		width: largest.width,
		height: Math.round(largest.width * RATIOS[kind])
	};
}
